   q('Day and night are caused by Earth\'s…','ቀንና ሌሊት የሚፈጠሩት በመሬት…',[('rotation','በራሷ ዛቢያ መሽከርከር'),('revolution','በፀሐይ ዙሪያ መዞር')]),q('One revolution around the Sun takes about…','በፀሐይ ዙሪያ አንድ ዙር…',[('365¼ days','365¼ ቀን'),('24 hours','24 ሰዓት'),('30 days','30 ቀን')]),
